 <?php $__env->startSection('content'); ?><section class="mx-auto max-w-4xl px-6 py-16"><a href="<?php echo e(route('admin.dashboard')); ?>" class="font-mono text-sm text-orange-600">← admin</a><h1 class="mt-6 text-4xl font-bold"><?php echo e($post->exists?'Edit artikel':'Artikel baru'); ?></h1><form method="POST" enctype="multipart/form-data" action="<?php echo e($post->exists?route('admin.posts.update',$post):route('admin.posts.store')); ?>" class="mt-10 space-y-6"><?php echo csrf_field(); ?> <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($post->exists): ?> <?php echo method_field('PUT'); ?> <?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?><label class="block text-sm font-medium">Judul<input name="title" value="<?php echo e(old('title',$post->title)); ?>" required class="mt-2 w-full rounded-lg border-stone-300 bg-white p-3 dark:border-stone-700 dark:bg-stone-900"></label><label class="block text-sm font-medium">Excerpt<textarea name="excerpt" rows="2" class="mt-2 w-full rounded-lg border-stone-300 bg-white p-3 dark:border-stone-700 dark:bg-stone-900"><?php echo e(old('excerpt',$post->excerpt)); ?></textarea></label><div class="grid gap-6 md:grid-cols-2"><label class="block text-sm font-medium">Kategori<select name="category_id" class="mt-2 w-full rounded-lg border-stone-300 bg-white p-3 dark:border-stone-700 dark:bg-stone-900"><option value="">Tanpa kategori</option><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::openLoop(); ?><?php endif; ?><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $category): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::startLoopIteration(); ?><?php endif; ?><option value="<?php echo e($category->id); ?>" <?php if(old('category_id',$post->category_id)==$category->id): echo 'selected'; endif; ?>><?php echo e($category->name); ?></option><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::endLoop(); ?><?php endif; ?><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php \Livewire\Features\SupportCompiledWireKeys\SupportCompiledWireKeys::closeLoop(); ?><?php endif; ?></select></label><label class="block text-sm font-medium">Status<select name="status" class="mt-2 w-full rounded-lg border-stone-300 bg-white p-3 dark:border-stone-700 dark:bg-stone-900"><option value="draft" <?php if(old('status',$post->status)==='draft'): echo 'selected'; endif; ?>>Draft</option><option value="published" <?php if(old('status',$post->status)==='published'): echo 'selected'; endif; ?>>Published</option></select></label></div><label class="block text-sm font-medium">Cover image<input name="cover_image" type="file" accept="image/*" class="mt-2 block w-full text-sm"></label><label class="block text-sm font-medium">Markdown body<textarea name="body" rows="22" required class="mt-2 w-full rounded-lg border-stone-300 bg-white p-4 font-mono text-sm dark:border-stone-700 dark:bg-stone-900"><?php echo e(old('body',$post->body)); ?></textarea></label><div class="grid gap-6 md:grid-cols-2"><label class="block text-sm font-medium">SEO title<input name="seo_title" value="<?php echo e(old('seo_title',$post->seo_title)); ?>" class="mt-2 w-full rounded-lg border-stone-300 p-3 dark:border-stone-700 dark:bg-stone-900"></labe